(context) => {
  const o = context.observation;
  const me = o.me;
  const keys = o.keys || [];
  const doors = o.doors || [];
  const parcels = o.parcels || [];
  if (!me || doors.length === 0) return undefined;
  const pending = parcels.find((p) => p && !p.carriedBy && !(p.x === me.x && p.y === me.y));
  if (!pending) return undefined;
  const co = keys.find((k) => k && k.x === me.x && k.y === me.y);
  if (!co) return undefined;
  const keyPos = '(' + co.x + ',' + co.y + ')';
  const doorPos = doors[0] ? '(' + doors[0].x + ',' + doors[0].y + ')' : '';
  return { action: { kind: 'pickup' }, confidence: 0.9, rationale: 'Key co-located at ' + keyPos + ' is uncollected while door ' + doorPos + ' gates uncarried parcel (' + pending.id + '); collect the key first to satisfy the gate prerequisite (key-door-delivery blocked 3 moves by skipping this).' };
}
